const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountFuji = ee.Geometry.Point([138.7274, 35.3606]).buffer(10000); // 10km buffer around Mount Fuji

  // Define date ranges for December 2019 and 2020
  const dec2019 = ['2019-12-01', '2019-12-31'];
  const dec2020 = ['2020-12-01', '2020-12-31'];

  // Function to calculate NDSI
  function calculateNDSI(img) {
    const ndsi = img.normalizedDifference(['B3', 'B11']).rename('NDSI'); // Green(B3) and SWIR(B11)
    return img.addBands(ndsi);
  }

  // Function to mask clouds
  function maskClouds(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return img.updateMask(mask);
  }

  // 2. Data Acquisition & Check
  let col2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(mountFuji)
    .filterDate(dec2019[0], dec2019[1])
    .map(maskClouds)
    .map(calculateNDSI);

  let col2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(mountFuji)
    .filterDate(dec2020[0], dec2020[1])
    .map(maskClouds)
    .map(calculateNDSI);

  // Check collection sizes
  const size2019 = col2019.size().getInfo();
  const size2020 = col2020.size().getInfo();

  console.log(`2019 Images: ${size2019}, 2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composites
  const composite2019 = col2019.median();
  const composite2020 = col2020.median();

  // 3. Processing - Get pixel counts and mean NDSI
  const stats2019 = composite2019.select('NDSI').reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: mountFuji,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2020 = composite2020.select('NDSI').reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: mountFuji,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean2019 = stats2019.get('NDSI_mean').getInfo();
  const count2019 = stats2019.get('NDSI_count').getInfo();
  const mean2020 = stats2020.get('NDSI_mean').getInfo();
  const count2020 = stats2020.get('NDSI_count').getInfo();

  console.log(`2019: Mean NDSI=${mean2019?.toFixed(3)}, Pixels=${count2019}`);
  console.log(`2020: Mean NDSI=${mean2020?.toFixed(3)}, Pixels=${count2020}`);

  // 4. Validation & Final Answer
  if (count2019 === 0 || count2020 === 0) {
    console.log("<answer>C2</answer>");
  } else if (mean2019 === null || mean2020 === null || 
             isNaN(mean2019) || isNaN(mean2020) ||
             mean2019 < -1 || mean2019 > 1 || 
             mean2020 < -1 || mean2020 > 1) {
    console.log("<answer>C3</answer>");
  } else if (mean2020 < mean2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
